define(["core/ajax","core/notification"],function(Ajax,Notification){var generateSessionId=function(){var arr=new Uint8Array(24);window.crypto.getRandomValues(arr);return Array.prototype.map.call(arr,function(b){return b.toString(16).padStart(2,"0")}).join("")};var escapeHtml=function(text){var div=document.createElement("div");div.appendChild(document.createTextNode(text));return div.innerHTML};var formatMessage=function(text){var html=escapeHtml(text);html=html.replace(/```([\s\S]*?)```/g,"<pre><code>$1</code></pre>");html=html.replace(/`([^`]+)`/g,"<code>$1</code>");html=html.replace(/\*\*(.+?)\*\*/g,"<strong>$1</strong>");html=html.replace(/__(.+?)__/g,"<strong>$1</strong>");html=html.replace(/\*(.+?)\*/g,"<em>$1</em>");html=html.replace(/_(.+?)_/g,"<em>$1</em>");html=html.replace(/\n/g,"<br>");return html};return{init:function(config){var container=document.getElementById("aichatbot-container");var messages=document.getElementById("aichatbot-messages");var input=document.getElementById("aichatbot-input");var sendBtn=document.getElementById("aichatbot-send");var clearBtn=document.getElementById("aichatbot-clear");if(!container||!messages||!input||!sendBtn){return}var storageKey="aichatbot_session_"+config.contextid+"_"+config.userid;var sessionId=sessionStorage.getItem(storageKey)||generateSessionId();sessionStorage.setItem(storageKey,sessionId);var isWaiting=false;var scrollToBottom=function(){messages.scrollTop=messages.scrollHeight};var appendMessage=function(role,text,isHtml){var wrapper=document.createElement("div");wrapper.className="aichatbot-message aichatbot-message-"+(role==="user"?"user":"bot");var bubble=document.createElement("div");bubble.className="aichatbot-bubble";if(isHtml){bubble.innerHTML=text}else{bubble.innerHTML=formatMessage(text)}wrapper.appendChild(bubble);messages.appendChild(wrapper);scrollToBottom();return wrapper};var showThinking=function(){var wrapper=document.createElement("div");wrapper.className="aichatbot-message aichatbot-message-bot aichatbot-thinking";wrapper.id="aichatbot-thinking";wrapper.innerHTML='<div class="aichatbot-bubble aichatbot-bubble-thinking"><span class="aichatbot-dot"></span><span class="aichatbot-dot"></span><span class="aichatbot-dot"></span></div>';messages.appendChild(wrapper);scrollToBottom()};var removeThinking=function(){var el=document.getElementById("aichatbot-thinking");if(el){el.remove()}};var setInputDisabled=function(disabled){input.disabled=disabled;sendBtn.disabled=disabled;if(disabled){sendBtn.classList.add("aichatbot-send-btn--loading")}else{sendBtn.classList.remove("aichatbot-send-btn--loading")}};var sendMessage=function(){var text=input.value.trim();if(!text||isWaiting){return}isWaiting=true;setInputDisabled(true);input.value="";input.style.height="auto";appendMessage("user",text,false);showThinking();var calls=Ajax.call([{methodname:"block_aichatbot_send_message",args:{contextid:config.contextid,sessionid:sessionId,message:text}}]);calls[0].then(function(result){removeThinking();if(result.success){appendMessage("assistant",result.response,false)}else{appendMessage("assistant","&#9888;&#65039; "+escapeHtml(result.response),true)}return result}).catch(function(err){removeThinking();Notification.exception(err);appendMessage("assistant","&#9888;&#65039; "+escapeHtml(err.message||"Unexpected error."),true)}).then(function(){isWaiting=false;setInputDisabled(false);input.focus();return}).catch(function(){isWaiting=false;setInputDisabled(false);input.focus()})};sendBtn.addEventListener("click",sendMessage);input.addEventListener("keydown",function(e){if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();sendMessage()}});input.addEventListener("input",function(){input.style.height="auto";input.style.height=Math.min(input.scrollHeight,120)+"px"});if(clearBtn){clearBtn.addEventListener("click",function(){sessionId=generateSessionId();sessionStorage.setItem(storageKey,sessionId);var allMessages=messages.querySelectorAll(".aichatbot-message");allMessages.forEach(function(msg,i){if(i>0){msg.remove()}});input.focus()})}input.focus()}}});
